{"command": "python3 << 'EOF'
from PIL import Image, ImageOps, ImageDraw
im = Image.open('radiograph.jpg').convert('L')
def crop_grid(box, name, scale=2):
    c = im.crop(box).convert('RGB')
    d = ImageDraw.Draw(c)
    x0,y0,x1,y1 = box
    for gx in range(x0 - x0%50, x1, 50):
        col = (255,0,0) if gx%100==0 else (0,200,255)
        d.line([(gx-x0,0),(gx-x0,(y1-y0)*scale//1)], fill=col, width=1)
        if gx%100==0: d.text((gx-x0+2, 2), str(gx), fill=(255,0,0))
    for gy in range(y0 - y0%50, y1, 50):
        col = (255,0,0) if gy%100==0 else (0,200,255)
        d.line([(0,gy-y0),((x1-x0)*scale,gy-y0)], fill=col, width=1)
        if gy%100==0: d.text((2, gy-y0+2), str(gy), fill=(255,0,0))
    c = c.resize((c.width*scale, c.height*scale), Image.NEAREST)
    c = ImageOps.autocontrast(c, cutoff=1)
    c.save(f'/tmp/{name}.png')
crop_grid((600,250,1300,680), 'max_right_grid', 2)
EOF", "description": "Gridded crop of right maxilla band"}

